    /**
     * Method to retrieve the Evidence via EvidenceFetchOneSummary
     * @param 	summary EvidenceFetchOneSummary 
     * @return 	EvidenceFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Evidence getEvidence( EvidenceFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "EvidenceFetchOneSummary arg cannot be null" );
    	
    	Evidence entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Evidence
        	// --------------------------------------
        	CompletableFuture<Evidence> futureEntity = queryGateway.query(new FindEvidenceQuery( new LoadEvidenceFilter( summary.getEvidenceId() ) ), ResponseTypes.instanceOf(Evidence.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Evidence with id " + summary.getEvidenceId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Evidences
     *
     * @return 	List<Evidence> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Evidence> getAllEvidence() 
    throws ProcessingException {
        List<Evidence> list = null;

        try {
        	CompletableFuture<List<Evidence>> futureList = queryGateway.query(new FindAllEvidenceQuery(), ResponseTypes.multipleInstancesOf(Evidence.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Evidence";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

